/bin/zsh -lc "python -c \"import pandas as pd,numpy as np; from scipy.optimize import minimize; d=pd.read_csv('data/nls_ses_processed.csv'); y=d['BA DEGREE COMPLETED'].astype(int).to_numpy();
for dec in [1,2,3,4,5,6]:
 x=d.SES.round(dec).to_numpy(); X=np.c_[np.ones(len(x)),x]; f=lambda b:(np.logaddexp(0,X@b)-y*(X@b)).sum(); print(dec,minimize(f,[0,0],method='BFGS').x[1])\""

